package com.primehr.succession.domain;
import com.primehr.integration.humanresource.HumanResourceAssessmentSubject; import com.primehr.rsp.domain.RspAuditedEntity; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="succession_committee_member",uniqueConstraints=@UniqueConstraint(name="uk_succ_member_employee",columnNames={"agency_id","charter_version_id","employee_no"}))
public class SuccessionCommitteeMember extends RspAuditedEntity {
 public enum Role{CHAIR,VICE_CHAIR,MEMBER,SECRETARIAT}
 @Column(name="charter_version_id",nullable=false,length=36) private String charterVersionId; @Column(name="employee_id",nullable=false) private Long employeeId; @Column(name="employee_no",nullable=false,length=100) private String employeeNo; @Column(name="display_name",nullable=false,length=250) private String displayName; @Column(name="appointment_id") private Long appointmentId; @Column(name="job_position_id") private Long jobPositionId; @Column(name="plantilla_id") private Long plantillaId; @Enumerated(EnumType.STRING) @Column(name="member_role",nullable=false,length=30) private Role memberRole; @Column(name="voting_member",nullable=false) private boolean votingMember; @Column(name="effective_from",nullable=false) private LocalDate effectiveFrom; @Column(name="effective_to") private LocalDate effectiveTo; @Column(name="source_fingerprint",nullable=false,length=120) private String sourceFingerprint; @Column(name="source_fetched_at",nullable=false) private Instant sourceFetchedAt;
 protected SuccessionCommitteeMember(){}
 public SuccessionCommitteeMember(String agencyId,String charterVersionId,HumanResourceAssessmentSubject source,Role role,boolean voting,LocalDate from,LocalDate to){super(agencyId);this.charterVersionId=requiredText(charterVersionId,"charterVersionId");if(source==null||!source.eligible())throw new IllegalArgumentException("Committee member must be an eligible HRM employee");employeeId=source.employeeId();employeeNo=requiredText(source.employeeNo(),"employeeNo");displayName=requiredText(source.displayName(),"displayName");appointmentId=source.appointmentId();jobPositionId=source.jobPositionId();plantillaId=source.plantillaId();if(role==null||from==null)throw new IllegalArgumentException("Role and effectiveFrom are required");if(to!=null&&to.isBefore(from))throw new IllegalArgumentException("effectiveTo cannot precede effectiveFrom");if(role==Role.SECRETARIAT&&voting)throw new IllegalArgumentException("Secretariat cannot vote");memberRole=role;votingMember=voting;effectiveFrom=from;effectiveTo=to;sourceFingerprint=requiredText(source.sourceFingerprint(),"sourceFingerprint");sourceFetchedAt=source.fetchedAt()==null?Instant.now():source.fetchedAt();}
 public String getCharterVersionId(){return charterVersionId;} public Long getEmployeeId(){return employeeId;} public String getEmployeeNo(){return employeeNo;} public String getDisplayName(){return displayName;} public Long getAppointmentId(){return appointmentId;} public Long getJobPositionId(){return jobPositionId;} public Long getPlantillaId(){return plantillaId;} public Role getMemberRole(){return memberRole;} public boolean isVotingMember(){return votingMember;} public LocalDate getEffectiveFrom(){return effectiveFrom;} public LocalDate getEffectiveTo(){return effectiveTo;} public String getSourceFingerprint(){return sourceFingerprint;} public Instant getSourceFetchedAt(){return sourceFetchedAt;}
}
